employee_amount:
const employment = ctx.subject.employment;
const terms = get(employment, 'terms', {});
const facts = get(employment, 'employee_extension_data', {});
const premiums =
	Number(get(ctx.statutory, 'JKK.employer', 0)) +
	Number(get(ctx.statutory, 'JKM.employer', 0)) +
	Number(get(ctx.statutory, 'KESEHATAN.employer', 0));
const current = Math.max(0, Number(get(ctx.subtotals, 'ADDITIONAL_WAGES', 0)) + premiums);
const surcharge = get(facts, 'tax_id_validated', true) === false ? Number(ctx.lookup.missing_tax_id_multiplier) : 1;
const marital = get(employment, 'payroll.marital_status', 'SINGLE');
const gender = get(employment, 'payroll.gender', '');
const husband = get(facts, 'husband_no_income_certified', false) === true;
const marriedFemale = marital === 'MARRIED' && gender === 'FEMALE' && !husband;
const dependents = Math.min(
	Math.max(0, Math.trunc(Number(get(facts, 'ptkp_dependents_count', 0)))),
	Number(ctx.lookup.maximum_dependants)
);
const status = (marital === 'MARRIED' && !marriedFemale ? 'K/' : 'TK/') + String(dependents);
const ptkp = Number(get(ctx.lookup.ptkp_amount, status, 54000000));
const coverage = get(ctx.run, 'salary_coverage', {});
const periodStart = String(get(coverage, 'from', ctx.as_of));
const periodEnd = String(get(coverage, 'to', ctx.as_of));
const taxYear = periodStart.slice(0, 4);
const employerId = String(get(ctx.subject.employer, 'entity_id', ''));
const year = (get(ctx.history, 'payslips', []) || []).filter((slip) => {
	if (String(get(slip, 'period', '')).slice(0, 4) !== taxYear) return false;
	const entity = get(slip, 'entity_id', null);
	return entity == null || String(entity) === employerId;
});
const paid = (key) => year.reduce((total, slip) => total + Number(get(slip, key, 0)), 0);
const exit = get(employment, 'effective_range.to', null);
const final = periodStart.slice(5, 7) === '12' || (exit != null && exit <= periodEnd);
if (!final) {
	const table = get(ctx.lookup, 'ter_' + get(ctx.lookup.ptkp_ter_table, status, '1'), []);
	return round(bracket(current, table) * current * surcharge, Number(ctx.lookup.whole_unit), 'HALF_UP');
}
const yearStart = taxYear + '-01-01';
const employedFrom = get(employment, 'effective_range.from', yearStart);
const taxableFrom = employedFrom > yearStart ? employedFrom : yearStart;
const months = Math.min(
	12,
	Math.max(
		1,
		(Number(periodEnd.slice(0, 4)) - Number(taxableFrom.slice(0, 4))) * 12 +
			Number(periodEnd.slice(5, 7)) -
			Number(taxableFrom.slice(5, 7)) +
			1
	)
);
const annualGross =
	paid('gross_earnings') +
	paid('employer_statutory_schemes.JKK') +
	paid('employer_statutory_schemes.JKM') +
	paid('employer_statutory_schemes.KESEHATAN') +
	current;
const expense = Math.min(
	annualGross * Number(ctx.lookup.employment_expense_share),
	Number(ctx.lookup.monthly_employment_expense_limit) * months
);
const contributions =
	paid('employee_statutory_schemes.JHT') +
	paid('employee_statutory_schemes.JP') +
	Number(get(ctx.statutory, 'JHT.employee', 0)) +
	Number(get(ctx.statutory, 'JP.employee', 0));
const taxable = Math.max(0, annualGross - expense - contributions - ptkp);
const annual = round(
	ladder(round(taxable, Number(ctx.lookup.thousand_units), 'DOWN'), ctx.lookup.annual_ladder) * surcharge,
	Number(ctx.lookup.whole_unit),
	'HALF_UP'
);
return Math.max(0, annual - paid('tax_withheld'));

